package com.ecopassport.service; import com.ecopassport.model.Product; import org.springframework.stereotype.Service; @Service public class AiService{public void analyze(Product p){double f=p.getMaterial()!=null&&p.getMaterial().toLowerCase().contains("recycled")?.8:2.0; double c=p.getWeightKg()*f+p.getEnergyKwh()*.42+p.getTransportKm()*.00018*p.getWeightKg(); double s=Math.max(0,Math.min(100,100-c*2+p.getRecycledContent()*.2+(p.isRecyclable()?10:0))); p.setCarbonFootprint(r(c));p.setSustainabilityScore(r(s));p.setEcoRating(s>=85?"A":s>=70?"B":s>=55?"C":s>=40?"D":"E");p.setAiRecommendation(p.getRecycledContent()<30?"Increase recycled material content.":p.getTransportKm()>1000?"Consider shorter supply routes.":p.isRecyclable()?"Maintain current practices and monitor lifecycle data.":"Improve end-of-life recyclability.");} double r(double x){return Math.round(x*100)/100.0;}}
